fn float_to_str(n: Float) -> Str {
    if n < 0 {
        "-" + float_to_str(-n)
    } else {
        let n = trunc(n * 100.0)
        let n = n / 100.0
        if n == trunc(n) {
            int_to_str(trunc(n) + 0) + ".00"
