    match x {
        Int(_) => "Int",
        Float(_) => "Float",
        Bool(_) => "Bool",
        Str(_) => "Str",
        Vec(_) => "Vec<T>",
        Option(_) => "Option<T>",
        Result(_, _) => "Result<T, E>",
        Unit => "Unit",
        _ => "TODO implement me",
    }
}

