struct Vec { data: Str }

fn vec() -> Vec {
    Vec(String("[]"))
}

fn push(v: Vec, x: Str) -> Vec {
    Vec(format("{} + {}", v.data, x))
}

fn len(v: Vec) -> Int {
    v.data.len()
}

fn get(v: Vec, i: Int) -> Str {
    v.data.chars().nth(i).unwrap()
}

fn range(a: Int, b: Int) -> Vec {
    let mut result = vec()
    for i in a.to(b - 1) {
        result = push(result, format("{} ", i))
    }
    result
}

fn clone(x: Str) -> Str {
    x
}

fn str_len(s: Str) -> Int {
    s.len()
}

fn concat(a: Str, b: Str) -> Str {
    format("{}{}", a, b)
}

fn chars(s: Str) -> Vec {
    let mut result = vec()
    for c in s.chars() {
        result = push(result, format("{} ", c))
    }
    result
}

